#include <iostream>
#include <string>

std::string htmlifyMarkdown(const std::string& markdown) {
    // Remove HTML tags from the Markdown string
    std::string html;
    size_t start = 0, end = 0;
    while ((end = markdown.find(">", start)) != std::string::npos) {
        html += "<" + markdown.substr(start, end - start) + ">";
        start = end + 1;
    }
    html += "<" + markdown.substr(start, end - start) + ">";
    return html;
}

int main() {
    std::string markdown = R"(
    # Hello World!

    This is some sample text with HTML formatting.
    \[This is a link\]
    )";

    std::cout << htmlifyMarkdown(markdown) << std::endl;

    return 0;
}
```

